CREATE TABLE IF NOT EXISTS agent_run (id VARCHAR(36) PRIMARY KEY, task_type VARCHAR(64) NOT NULL, objective TEXT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'PENDING', as_of TIMESTAMP, supervisor_version VARCHAR(32) NOT NULL DEFAULT 'v1', participating_agents JSON, usage JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_subtask (id VARCHAR(36) PRIMARY KEY, agent_run_id VARCHAR(36) NOT NULL, agent VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, conclusion JSON, evidence_refs JSON, confidence REAL, usage JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agent_conflict (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_run_id VARCHAR(36) NOT NULL, dimension VARCHAR(64) NOT NULL, opinions JSON, resolution_policy VARCHAR(64) NOT NULL, resolved_value JSON, resolved_by VARCHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trade_intent (id VARCHAR(36) PRIMARY KEY, client_order_id VARCHAR(256) UNIQUE NOT NULL, decision_id VARCHAR(36) NOT NULL, strategy_id VARCHAR(128), symbol VARCHAR(32) NOT NULL, target_version VARCHAR(64) NOT NULL, payload JSON, status VARCHAR(32) NOT NULL DEFAULT 'CREATED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS execution_order (id VARCHAR(36) PRIMARY KEY, trade_intent_id VARCHAR(36) NOT NULL, mode VARCHAR(16) NOT NULL, status VARCHAR(32) NOT NULL, quantity INTEGER NOT NULL, limit_price REAL, broker_order_id VARCHAR(128), rejection_reasons JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS execution_fill (id VARCHAR(36) PRIMARY KEY, execution_order_id VARCHAR(36) NOT NULL, quantity INTEGER NOT NULL, price REAL NOT NULL, broker_fill_id VARCHAR(128), filled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS position_snapshot (id INTEGER PRIMARY KEY AUTOINCREMENT, as_of TIMESTAMP NOT NULL, source VARCHAR(32) NOT NULL, cash REAL NOT NULL, positions JSON);
CREATE TABLE IF NOT EXISTS execution_reconciliation (id INTEGER PRIMARY KEY AUTOINCREMENT, as_of TIMESTAMP DEFAULT CURRENT_TIMESTAMP, status VARCHAR(64) NOT NULL, differences JSON);
CREATE TABLE IF NOT EXISTS skill_proposal (id VARCHAR(36) PRIMARY KEY, skill_slug VARCHAR(128) NOT NULL, base_version INTEGER NOT NULL, status VARCHAR(32) NOT NULL, proposal JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS skill_evaluation (id INTEGER PRIMARY KEY AUTOINCREMENT, proposal_id VARCHAR(36) NOT NULL, stage VARCHAR(32) NOT NULL, result JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS strategy_definition (id VARCHAR(36) PRIMARY KEY, name VARCHAR(128) NOT NULL, version INTEGER NOT NULL, status VARCHAR(32) NOT NULL, definition JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
